mapper.select:
SELECT COUNT(*)
  FROM tbl_user_mission_info
 WHERE id = #{assignmentId}
   AND user_id = #{userId}
   AND result IN ('SUCCESS', 'FAIL')
   AND evaluated_at IS NOT NULL

mapper.update:
UPDATE tbl_user_mission_info
   SET result_checked_at = COALESCE(result_checked_at, #{checkedAt})
 WHERE id = #{assignmentId}
   AND user_id = #{userId}
   AND result IN ('SUCCESS', 'FAIL')
   AND evaluated_at IS NOT NULL

mapper.select:
SELECT result_checked_at
  FROM tbl_user_mission_info
 WHERE id = #{assignmentId}
   AND user_id = #{userId}
   AND result IN ('SUCCESS', 'FAIL')
   AND evaluated_at IS NOT NULL
